<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OrbitCare component preview</title>@vite(['resources/js/app.js'])</head><body><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><x-page-header title="Component preview" eyebrow="Development only" /><button class="btn btn-outline-secondary" data-theme-toggle></button></div><div class="row g-3"><div class="col-md-6"><div class="oc-card"><div class="oc-card-title">Statuses and source labels</div><div class="d-flex flex-wrap gap-2"><x-status-badge state="current"/><x-status-badge state="stale"/><x-status-badge state="no_data"/><x-source-label source="simulation"/><x-source-label source="manual"/></div></div></div><div class="col-md-6"><div class="oc-card"><div class="oc-card-title">Metric and completeness</div><div class="d-flex justify-content-between align-items-center"><x-metric-card :card="['icon'=>'bi-heart-pulse','label'=>'Resting heart rate','value'=>'61','unit'=>'bpm','observed_at'=>now(),'source'=>'simulation','freshness'=>'current','delta'=>3.0,'hint'=>null]"/><x-stat-ring :value="82"/></div></div></div><div class="col-12"><div class="oc-card"><x-empty-state title="Empty state" message="Clear, calm guidance appears when a record has no data yet."><a class="btn btn-primary mt-3" href="#">Add a reading</a></x-empty-state></div></div></div></main></body></html>
